INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (78, 231, 'General Documents of normal cargo for exporting business', '../', '<p></p><p style="color:#000000;text-indent:0px;"> General Documents of normal cargo for exporting business/基本单据</p> <p style="color:#000000;text-indent:0px;"> 1. 箱单 packing list</p> <p style="color:#000000;text-indent:0px;"> 2. 发票 invoice</p> <p style="color:#000000;text-indent:0px;"> 3. 合同 contract</p> <p style="color:#000000;text-indent:0px;"> 4. 提单 B/L</p> <p style="color:#000000;text-indent:0px;"> 5. 一般原产地证 CO (certificate of original)</p> <p style="color:#000000;text-indent:0px;"> 6. 技术参数 technology data</p> <p style="color:#000000;text-indent:0px;"> 7. 价格单子 price list</p> <p style="color:#000000;text-indent:0px;"> 8. 安全技术说明书 (MSDS )</p> <p style="color:#000000;text-indent:0px;"> 9. 货物明细单子（each rolls details sheets）</p> <p style="color:#000000;text-indent:0px;"> 10. 空白纸盖章 （blank stamped paper）</p> <p style="color:#000000;text-indent:0px;"> 11. 用途单（Usages/application of this film）</p> <p style="color:#000000;text-indent:0px;"> 12. 购买保险（ CIF ，保险单/insurance policy ）</p>', '2026-09-06 20:58:45');
