INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (78, 339, 'Our USD bank accounts (USD &amp; EUR) to receive T/T payment from oversea buyers, all over the world', '../upload/image/20211215/20211215213107_80691.jpg', '<p></p><p><span style="color:#009900;font-size:16px;">Our company''s bank accounts (USD &amp; EUR) to receive T/T payment from the buyers who come from all over the world.</span></p> <p><span style="color:#009900;font-size:16px;"><br/> </span></p> <p style="color:#000000;text-indent:0px;"> <span style="color:#009900;font-size:16px;"><span style="color:#009900;font-size:16px;"><strong>A.) </strong>BANK ACCOUNT INFORMATION: <br/> </span></span></p> <p style="color:#000000;text-indent:0px;"> <span style="color:#009900;font-size:16px;"></span></p> <p align="left" class="MsoNormal" style="text-align:left;"> <span style="color:#009900;">OUR COMPANY’S BANK ACCOUNT (USD) TO RECEIVE T/T PAYMENT FROM THE BUYERS WHO COME FROM ALL OVER THE WORLD.</span></p> <p align="left" class="MsoNormal" style="text-align:left;"> <a name="#"></a><span style="color:#009900;">OUR COMPANY’S BANK ACCOUNT INFORMATION ---- </span><b><span style="color:#009900;">IN</span></b> <b><span style="color:#009900;">USD</span></b><span style="color:#009900;">:</span></p> <p align="left" class="MsoNormal" style="text-align:left;"> <span style="color:#009900;">THE BENEFICIARY''S NAME: </span><b><span style="color:#009900;">ASIA PACIFIC INDUSTRY GROUP CO., LIMITED</span></b></p> <p align="left" class="MsoNormal" style="text-align:left;"> <span style="color:#009900;">THE ADDRESS OF BENEFICIARY: NO.3399, LUZHOU AVE., BAOHE DIST., 230051, HEFEI CITY, ANHUI PROVINCE, P.R. CHINA TEL.: 86-18919654871 EMAIL: SALE@APIGCL.COM</span></p> <p align="left" class="MsoNormal" style="text-align:left;"> <span style="color:#009900;">BANK NAME: </span><b><span style="color:#009900;">STANDARD CHARTERED BANK (CHINA) LTD</span></b></p> <p align="left" class="MsoNormal" style="text-alig